<section class="dashboard-hero"><span class="hero-icon"><i class="bi bi-bag"></i></span><div><p class="section-label">Stocks auxiliaires</p><h2>Emballages vides</h2><p>Achats, DAE, BSE, transferts, consommation et casse par site.</p></div></section>
<?php if($success):?><div class="app-alert app-alert-success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="app-alert app-alert-error"><?=e($error)?></div><?php endif;?>
<section class="table-panel"><div class="table-responsive"><table class="enterprise-table"><thead><tr><th>Site</th><th>Format</th><th>Magasin</th><th>Réservé</th><th>Atelier</th><th>Minimum</th><th>Jours stock</th><th>Casse 30j</th><th>Coût/tonne</th></tr></thead><tbody><?php foreach($stocks as$s):?><?php $daily=(float)$s['consumed_30d']/30;$days=$daily>0?((int)$s['physical_quantity']+(int)$s['operational_quantity'])/$daily:null;$den=(float)$s['consumed_30d']+(float)$s['defective_30d'];$break=$den>0?(float)$s['defective_30d']/$den*100:0;$cost=(float)$s['unit_capacity_kg']>0?1000/(float)$s['unit_capacity_kg']*(float)$s['average_unit_cost']:0;?><tr><td><?=e($s['site_code'])?></td><td><strong><?=e($s['code'])?></strong><br><?=e($s['name'])?></td><td><?=e($s['physical_quantity'])?></td><td><?=e($s['reserved_quantity'])?></td><td><?=e($s['operational_quantity'])?></td><td><?php if(Auth::can('empty-packaging','administer')):?><form method="post" action="<?=e(base_url('empty-packaging/stocks/'.$s['id'].'/minimum'))?>"><?=csrf_field()?><input type="number" min="0" name="minimum_quantity" value="<?=e($s['minimum_quantity'])?>" style="width:90px"><button>✓</button></form><?php else:?><?=e($s['minimum_quantity'])?><?php endif;?> <?=$s['physical_quantity']<$s['minimum_quantity']?'⚠':''?></td><td><?=e($days===null?'∞':number_format($days,1,',',' '))?></td><td><?=e(number_format($break,2,',',' '))?>%</td><td><?=e(number_format($cost,2,',',' '))?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="form-panel"><h3>Achat d’emballages</h3><form method="post" action="<?=e(base_url('empty-packaging/purchases'))?>" class="enterprise-form"><?=csrf_field()?><div class="form-grid"><label><span>Fournisseur</span><select name="supplier_id" required><?php foreach($references['suppliers'] as$x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select></label><label><span>Format</span><select name="packaging_item_id" required><?php foreach($references['items'] as$x):?><option value="<?=$x['id']?>"><?=e($x['code'].' — '.$x['name'])?></option><?php endforeach;?></select></label><label><span>Quantité</span><input type="number" min="1" name="quantity" required></label><label><span>Coût unitaire</span><input type="number" min="0" step="0.0001" name="unit_cost" required></label></div><button class="btn-primary">Créer l’achat</button></form></section>
<section class="table-panel"><h3>Achats à traiter</h3><div class="table-responsive"><table class="enterprise-table"><tbody><?php foreach($purchases as$p):?><tr><td><?=e($p['purchase_number'])?></td><td><?=e($p['supplier_name'])?></td><td><?=e($p['status'])?></td><td><?php if($p['status']==='draft'):?><form method="post" action="<?=e(base_url('empty-packaging/purchases/'.$p['id'].'/approve'))?>"><?=csrf_field()?><button class="btn-primary">Approuver</button></form><?php else:?><form method="post" action="<?=e(base_url('empty-packaging/purchases/'.$p['id'].'/receive'))?>"><?=csrf_field()?><input type="hidden" name="idempotency_key" value="<?=e(bin2hex(random_bytes(12)))?>"><button class="btn-primary">Réceptionner</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="form-panel"><h3>DAE</h3><form method="post" action="<?=e(base_url('empty-packaging/requests'))?>" class="enterprise-form"><?=csrf_field()?><div class="form-grid"><label><span>Format</span><select name="packaging_item_id"><?php foreach($references['items'] as$x):?><option value="<?=$x['id']?>"><?=e($x['code'])?></option><?php endforeach;?></select></label><label><span>Quantité</span><input type="number" min="1" name="quantity" required></label><label><span>Date besoin</span><input type="datetime-local" name="needed_at" value="<?=date('Y-m-d\TH:i')?>"></label><label><span>Justification</span><input name="justification"></label></div><button class="btn-primary">Soumettre DAE</button></form></section>
<section class="table-panel"><h3>DAE à traiter</h3><table class="enterprise-table"><tbody><?php foreach($requests as$r):?><tr><td><?=e($r['request_number'])?></td><td><?=e($r['status'])?></td><td><form method="post" action="<?=e(base_url('empty-packaging/requests/'.$r['id'].'/'.($r['status']==='submitted'?'approve':'issue')))?>"><?=csrf_field()?><button class="btn-primary"><?=e($r['status']==='submitted'?'Approuver':'Émettre BSE')?></button></form></td></tr><?php endforeach;?></tbody></table></section>
<section class="form-panel"><h3>Transfert / défectueux</h3><div class="form-grid"><form method="post" action="<?=e(base_url('empty-packaging/transfers'))?>"><?=csrf_field()?><select name="packaging_item_id"><?php foreach($references['items'] as$x):?><option value="<?=$x['id']?>"><?=e($x['code'])?></option><?php endforeach;?></select><select name="destination_site_id"><?php foreach($references['sites'] as$x):?><option value="<?=$x['id']?>"><?=e($x['code'])?></option><?php endforeach;?></select><input type="number" min="1" name="quantity" required><button class="btn-primary">Transférer</button></form><form method="post" action="<?=e(base_url('empty-packaging/defects'))?>"><?=csrf_field()?><select name="packaging_item_id"><?php foreach($references['items'] as$x):?><option value="<?=$x['id']?>"><?=e($x['code'])?></option><?php endforeach;?></select><input type="number" min="1" name="quantity" required><input name="reason" placeholder="Motif" required><button class="btn-primary">Déclarer défectueux</button></form></div></section>
<section class="table-panel"><h3>Transferts en cours</h3><table class="enterprise-table"><tbody><?php foreach($transfers as$t):?><tr><td><?=e($t['transfer_number'])?></td><td><?=e($t['source_code'].' → '.$t['destination_code'])?></td><td><?=e($t['status'])?></td><td><form method="post" action="<?=e(base_url('empty-packaging/transfers/'.$t['id'].'/'.($t['status']==='draft'?'approve':'receive')))?>"><?=csrf_field()?><button class="btn-primary"><?=e($t['status']==='draft'?'Approuver/expédier':'Réceptionner')?></button></form></td></tr><?php endforeach;?></tbody></table></section>
